<template>
  <section class="page">
    <div class="page-heading"><div><h2>Gestion du temps</h2><p class="muted">Régimes, planning, anomalies et préparation des variables de paie.</p></div><button class="button" @click="load">Actualiser</button></div>
    <div v-if="error" class="alert error">{{ error }}</div><div v-if="notice" class="alert success">{{ notice }}</div>
    <div class="card"><h3>Régimes de travail</h3><form class="form-grid" @submit.prevent="saveRegime"><label>Code <input v-model="regime.code" required maxlength="40"></label><label>Libellé <input v-model="regime.libelle" required maxlength="150"></label><label>Heures par semaine <input type="number" v-model.number="regime.heuresHebdo" min="0.01" max="168" step="0.01" required></label><label>Jours par semaine <input type="number" v-model.number="regime.joursTravaillesParSemaine" min="0.1" max="7" step="0.1" required></label><label>Tolérance de retard (min) <input type="number" v-model.number="regime.toleranceRetardMin" min="0" required></label><button class="button primary">{{ regime.id ? 'Modifier le régime' : 'Créer le régime' }}</button><button v-if="regime.id" type="button" class="button" @click="resetRegime">Annuler</button></form><div class="table-wrap"><table><thead><tr><th>Code</th><th>Libellé</th><th>Heures hebdo.</th><th>Jours</th><th>Tolérance</th><th></th></tr></thead><tbody><tr v-for="r in regimes" :key="r.id"><td>{{ r.code }}</td><td>{{ r.libelle }}</td><td>{{ r.heuresHebdo }} h</td><td>{{ r.joursTravaillesParSemaine }}</td><td>{{ r.toleranceRetardMin }} min</td><td class="actions"><button class="button" @click="editRegime(r)">Éditer</button><button class="danger-button" @click="deleteRegime(r)">Supprimer</button></td></tr><tr v-if="!regimes.length"><td colspan="6" class="empty">Aucun régime.</td></tr></tbody></table></div>
      <div class="card inset"><h4>Horaires types du régime</h4><label>Régime <select v-model="selectedRegime" @change="loadHours"><option value="">Choisir</option><option v-for="r in regimes" :key="r.id" :value="r.id">{{ r.libelle }}</option></select></label><div class="table-wrap"><table><thead><tr><th>Jour (1=lundi)</th><th>Travaillé</th><th>Début</th><th>Fin</th><th>Pause (min)</th></tr></thead><tbody><tr v-for="h in hours" :key="h.jourSemaine"><td>{{ weekdays[h.jourSemaine-1] }}</td><td><input type="checkbox" v-model="h.travaille"></td><td><input type="time" v-model="h.heureDebut"></td><td><input type="time" v-model="h.heureFin"></td><td><input type="number" min="0" v-model.number="h.pauseMinutes"></td></tr></tbody></table></div><button class="button primary" :disabled="!selectedRegime" @click="saveHours">Enregistrer les horaires</button></div>
    </div>
    <div class="detail-grid"><article class="card"><h3>Assigner un régime</h3><form class="form-grid" @submit.prevent="assignRegime"><label>Employé <select v-model="assignment.employeId" required><option value="">Choisir</option><option v-for="e in employees" :key="e.id" :value="e.id">{{ e.prenom }} {{ e.nom }} — {{ e.matricule }}</option></select></label><label>Régime <select v-model="assignment.regimeTravailId" required><option value="">Choisir</option><option v-for="r in regimes" :key="r.id" :value="r.id">{{ r.libelle }}</option></select></label><label>Début de validité <input type="date" v-model="assignment.dateDebut" required></label><label>Fin de validité (facultatif) <input type="date" v-model="assignment.dateFin"></label><button class="button primary">Assigner</button></form></article>
      <article class="card"><h3>Générer un planning</h3><form class="form-grid" @submit.prevent="generate"><label>Portée <select v-model="generation.scope"><option value="employe">Un employé</option><option value="departement">Un département</option></select></label><label v-if="generation.scope==='employe'">Employé <select v-model="generation.employeId"><option value="">Choisir</option><option v-for="e in employees" :key="e.id" :value="e.id">{{ e.prenom }} {{ e.nom }}</option></select></label><label v-else>Département <select v-model="generation.departementId"><option value="">Choisir</option><option v-for="d in departments" :key="d.id" :value="d.id">{{ d.nom }}</option></select></label><label>Du <input type="date" v-model="generation.du" required></label><label>Au <input type="date" v-model="generation.au" required></label><button class="button primary">Générer</button></form></article></div>
    <div class="detail-grid"><article class="card"><h3>Jours fériés</h3><label>Année <input type="number" v-model.number="holidayYear" min="2000" @change="loadHolidays"></label><form class="inline-form" @submit.prevent="addHoliday"><input type="date" v-model="holiday.date" required><input v-model="holiday.libelle" placeholder="Libellé" required><label><input type="checkbox" v-model="holiday.paye"> Payé</label><button class="button primary">Ajouter</button></form><div class="table-wrap"><table><thead><tr><th>Date</th><th>Libellé</th><th>Payé</th></tr></thead><tbody><tr v-for="h in holidays" :key="h.id"><td>{{ h.date }}</td><td>{{ h.libelle }}</td><td>{{ h.paye?'Oui':'Non' }}</td></tr></tbody></table></div></article>
      <article class="card"><h3>Importer les pointages (CSV)</h3><p class="muted">Colonnes attendues : matricule, date_heure, sens (ENTREE/SORTIE).</p><form class="inline-form" @submit.prevent="importFile"><input type="file" accept=".csv,text/csv" @change="file=$event.target.files?.[0]" required><button class="button primary" :disabled="!file">Importer</button></form><pre v-if="importReport" class="report">{{ JSON.stringify(importReport,null,2) }}</pre></article></div>
    <div class="card"><h3>Anomalies de pointage</h3><div class="toolbar"><label>Statut <select v-model="anomalyStatus" @change="loadAnomalies"><option value="OUVERTE">Ouvertes</option><option value="JUSTIFIEE">Justifiées</option><option value="CORRIGEE">Corrigées</option><option value="IGNOREE">Ignorées</option></select></label><label>Type <select v-model="anomalyType" @change="loadAnomalies"><option value="">Tous</option><option v-for="type in anomalyTypes" :key="type">{{ type }}</option></select></label><button class="button" @click="loadAnomalies">Filtrer</button></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Employé</th><th>Type</th><th>Statut</th><th>Commentaire</th><th>Action</th></tr></thead><tbody><tr v-for="a in anomalies" :key="a.id"><td>{{ a.date }}</td><td>{{ nameOf(a.employeId) }}</td><td>{{ a.type }}</td><td>{{ a.statut }}</td><td>{{ a.commentaire }}</td><td><button v-if="a.statut==='OUVERTE'" class="button" @click="treatAnomaly(a)">Traiter</button></td></tr><tr v-if="!anomalies.length"><td colspan="6" class="empty">Aucune anomalie.</td></tr></tbody></table></div></div>
    <div class="card"><h3>Périodes et variables de paie</h3><form class="inline-form" @submit.prevent="createPeriod"><label>Année <input type="number" v-model.number="periodDraft.annee" required></label><label>Mois <input type="number" min="1" max="12" v-model.number="periodDraft.mois" required></label><button class="button">Créer / ouvrir la période</button></form><div class="table-wrap"><table><thead><tr><th>Période</th><th>Statut</th><th>Validation / export</th><th>Actions</th></tr></thead><tbody><tr v-for="p in periods" :key="p.id"><td>{{ p.mois }}/{{ p.annee }}</td><td>{{ p.statut }}</td><td>{{ p.dateValidation || p.dateExport || '—' }}</td><td class="actions"><button v-if="p.statut==='OUVERTE'" class="button primary" @click="validatePeriod(p)">Valider</button><button v-if="p.statut!=='OUVERTE'" class="button" @click="reopenPeriod(p)">Réouvrir</button><button v-if="p.statut!=='OUVERTE'" class="button" @click="exportPeriod(p,'json')">JSON</button><button v-if="p.statut!=='OUVERTE'" class="button" @click="exportPeriod(p,'csv')">CSV</button></td></tr><tr v-if="!periods.length"><td colspan="4" class="empty">Aucune période.</td></tr></tbody></table></div></div>
    <div class="card"><h3>Indicateurs mensuels</h3><label>Mois <input type="month" v-model="reportMonth" @change="loadReports"></label><div class="table-wrap"><table><thead><tr><th>Département</th><th>Effectif</th><th>Taux de jours en retard</th><th>Heures supplémentaires</th><th>Taux d’absence constatée</th></tr></thead><tbody><tr v-for="row in reports" :key="row.department"><td>{{ row.department }}</td><td>{{ row.count }}</td><td>{{ row.workDays ? Math.round(row.lateDays/row.workDays*100) : 0 }} %</td><td>{{ formatDuration(row.overtime) }}</td><td>{{ row.presentAndAbsent ? Math.round(row.absence/row.presentAndAbsent*100) : 0 }} % ({{ formatDuration(row.absence) }})</td></tr></tbody></table></div><p class="muted">Ratios calculés sur les récapitulatifs du mois chargés pour les employés visibles dans votre périmètre.</p></div>
  </section>
</template>
<script setup>
import { onMounted, ref } from 'vue'
import api from '@/api/axios'
import { formatApiError } from '@/utils/errors'
const weekdays=['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'],anomalyTypes=['ENTREE_MANQUANTE','SORTIE_MANQUANTE','DOUBLON','HORS_PLANNING','DUREE_EXCESSIVE','RETARD_NON_JUSTIFIE','ABSENCE_SANS_CONGE']
const regimes=ref([]),employees=ref([]),departments=ref([]),hours=ref([]),selectedRegime=ref(''),holidays=ref([]),anomalies=ref([]),periods=ref([]),reports=ref([]),error=ref(''),notice=ref(''),file=ref(null),importReport=ref(null),anomalyStatus=ref('OUVERTE'),anomalyType=ref(''),holidayYear=ref(new Date().getFullYear()),reportMonth=ref(new Date().toISOString().slice(0,7))
const regime=ref({code:'',libelle:'',heuresHebdo:40,joursTravaillesParSemaine:5,toleranceRetardMin:10}),assignment=ref({employeId:'',regimeTravailId:'',dateDebut:new Date().toISOString().slice(0,10),dateFin:''}),generation=ref({scope:'employe',employeId:'',departementId:'',du:new Date().toISOString().slice(0,10),au:new Date().toISOString().slice(0,10)}),holiday=ref({date:'',libelle:'',paye:true}),periodDraft=ref({annee:new Date().getFullYear(),mois:new Date().getMonth()+1})
function nameOf(id){const e=employees.value.find(x=>Number(x.id)===Number(id));return e?`${e.prenom} ${e.nom}`:`#${id}`}function formatDuration(n){return `${Math.floor((Number(n)||0)/60)} h ${String((Number(n)||0)%60).padStart(2,'0')}`}
async function load(){error.value='';try{[regimes.value,employees.value,periods.value]=await Promise.all([api.get('/regimes-travail').then(r=>r.data),api.get('/employes').then(r=>r.data),api.get('/periodes').then(r=>r.data)]);const map=new Map();for(const e of employees.value){const a=e.affectationCourante;if(a?.departementId)map.set(a.departementId,{id:a.departementId,nom:a.departement})}departments.value=[...map.values()];await Promise.all([loadHolidays(),loadAnomalies(),loadReports()])}catch(e){error.value=formatApiError(e)}}
async function saveRegime(){try{let saved;if(regime.value.id)saved=(await api.put(`/regimes-travail/${regime.value.id}`,regime.value)).data;else saved=(await api.post('/regimes-travail',regime.value)).data;notice.value='Régime enregistré.';regimes.value=(await api.get('/regimes-travail')).data;selectedRegime.value=saved.id;resetRegime();await loadHours()}catch(e){error.value=formatApiError(e)}}function editRegime(r){regime.value={...r}}function resetRegime(){regime.value={code:'',libelle:'',heuresHebdo:40,joursTravaillesParSemaine:5,toleranceRetardMin:10}}
async function deleteRegime(r){if(!window.confirm(`Supprimer le régime ${r.libelle} ?`))return;try{await api.delete(`/regimes-travail/${r.id}`);regimes.value=regimes.value.filter(x=>x.id!==r.id);if(String(selectedRegime.value)===String(r.id)){selectedRegime.value='';hours.value=[]}notice.value='Régime supprimé.'}catch(e){error.value=formatApiError(e)}}
async function loadHours(){if(!selectedRegime.value){hours.value=[];return}try{const saved=(await api.get(`/regimes-travail/${selectedRegime.value}/horaires`)).data;hours.value=Array.from({length:7},(_,i)=>saved.find(h=>h.jourSemaine===i+1)||{jourSemaine:i+1,heureDebut:'08:00',heureFin:'17:00',pauseMinutes:60,travaille:i<5})}catch(e){error.value=formatApiError(e)}}
async function saveHours(){try{await api.put(`/regimes-travail/${selectedRegime.value}/horaires`,hours.value);notice.value='Horaires types enregistrés.'}catch(e){error.value=formatApiError(e)}}
async function assignRegime(){try{await api.post('/employe-regimes',{...assignment.value,employeId:Number(assignment.value.employeId),regimeTravailId:Number(assignment.value.regimeTravailId),dateFin:assignment.value.dateFin||null});notice.value='Régime assigné.'}catch(e){error.value=formatApiError(e)}}
async function generate(){try{const body={du:generation.value.du,au:generation.value.au};if(generation.value.scope==='employe')body.employeId=Number(generation.value.employeId);else body.departementId=Number(generation.value.departementId);const result=(await api.post('/plannings/generer',body)).data;notice.value=`Planning généré : ${result.lignesCreees} ligne(s).`}catch(e){error.value=formatApiError(e)}}
async function loadHolidays(){try{holidays.value=(await api.get('/jours-feries',{params:{annee:holidayYear.value}})).data}catch(e){error.value=formatApiError(e)}}async function addHoliday(){try{await api.post('/jours-feries',holiday.value);holiday.value={date:'',libelle:'',paye:true};notice.value='Jour férié ajouté.';await loadHolidays()}catch(e){error.value=formatApiError(e)}}
async function importFile(){if(!file.value)return;try{const data=new FormData();data.append('fichier',file.value);importReport.value=(await api.post('/pointages/import',data,{headers:{'Content-Type':'multipart/form-data'}})).data;notice.value='Import terminé.'}catch(e){error.value=formatApiError(e)}}
async function loadAnomalies(){try{anomalies.value=(await api.get('/anomalies',{params:{statut:anomalyStatus.value||undefined,type:anomalyType.value||undefined}})).data}catch(e){error.value=formatApiError(e)}}async function treatAnomaly(a){const commentaire=window.prompt('Commentaire de traitement :');if(!commentaire?.trim())return;try{await api.post(`/anomalies/${a.id}/corriger`,{commentaire});await loadAnomalies()}catch(e){error.value=formatApiError(e)}}
async function createPeriod(){try{await api.post('/periodes',periodDraft.value);notice.value='Période disponible.';periods.value=(await api.get('/periodes')).data}catch(e){error.value=formatApiError(e)}}async function validatePeriod(p){try{await api.post(`/periodes/${p.id}/valider`,{});notice.value='Période validée et variables produites.';periods.value=(await api.get('/periodes')).data}catch(e){const message=e.response?.data?.message||'';if(message.toLowerCase().includes('anomalie')){const motif=window.prompt('La période comporte des anomalies ouvertes. Motif obligatoire pour déroger :');if(!motif?.trim())return;try{await api.post(`/periodes/${p.id}/valider`,{motifDerogation:motif});notice.value='Période validée avec dérogation tracée.';periods.value=(await api.get('/periodes')).data}catch(retry){error.value=formatApiError(retry)}}else error.value=formatApiError(e)}}async function reopenPeriod(p){const motif=window.prompt('Motif de réouverture obligatoire :');if(!motif?.trim())return;try{await api.post(`/periodes/${p.id}/reouvrir`,{motif});periods.value=(await api.get('/periodes')).data;notice.value='Période réouverte.'}catch(e){error.value=formatApiError(e)}}
async function exportPeriod(p,format){try{const response=await api.get(`/periodes/${p.id}/variables-paie`,{params:{format},responseType:format==='csv'?'blob':'json'});if(format==='csv'){const url=URL.createObjectURL(response.data),a=document.createElement('a');a.href=url;a.download=`variables-paie-${p.id}.csv`;a.click();URL.revokeObjectURL(url)}else{const url=URL.createObjectURL(new Blob([JSON.stringify(response.data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`variables-paie-${p.id}.json`;a.click();URL.revokeObjectURL(url)}periods.value=(await api.get('/periodes')).data}catch(e){error.value=formatApiError(e)}}
async function loadReports(){if(!employees.value.length)return;const values=await Promise.all(employees.value.map(async e=>{try{return {employee:e,recap:(await api.get(`/employes/${e.id}/temps/recap`,{params:{mois:reportMonth.value}})).data}}catch{return {employee:e,recap:{}}}}));const grouped=new Map();for(const {employee,recap} of values){const dept=employee.departement||'Sans département',row=grouped.get(dept)||{department:dept,count:0,lateDays:0,workDays:0,overtime:0,absence:0,presentAndAbsent:0};row.count++;const days=recap.jours||[],absence=Number(recap.minutes_absence??recap.minutesAbsence)||0,worked=Number(recap.minutes_travaillees??recap.minutesTravaillees)||0;row.lateDays+=days.filter(d=>Number(d.minutes_retard??d.minutesRetard)>0).length;row.workDays+=days.filter(d=>Number(d.minutes_travaillees??d.minutesTravaillees)>0||Number(d.minutes_absence??d.minutesAbsence)>0).length;row.overtime+=Number(recap.minutes_sup??recap.minutesSup)||0;row.absence+=absence;row.presentAndAbsent+=absence+worked;grouped.set(dept,row)}reports.value=[...grouped.values()]}
onMounted(load)
</script>
